import React, { useState } from 'react';
import './App.css';

function App() {
  const [simOutput, setSimOutput] = useState('');
  const [selectedFile, setSelectedFile] = useState(null);
  const [loading, setLoading] = useState(false);
  const [fileName, setFileName] = useState('');
  const [graphicsStatus, setGraphicsStatus] = useState(null);
  const [clicked, setClicked] = useState(false);

  // Step-by-step simulation state
  const [processId, setProcessId] = useState(null);
  const [isStepping, setIsStepping] = useState(false);
  const [hasSimulationEnded, setHasSimulationEnded] = useState(false);
  const [stepCount, setStepCount] = useState(0);

  const handleFileChange = (e) => {
    const file = e.target.files[0];
    if (!file) return;
    setSelectedFile(file);
    setFileName(file.name);
    setSimOutput('');
    setGraphicsStatus(null);
    // Reset step-by-step state
    setProcessId(null);
    setIsStepping(false);
    setHasSimulationEnded(false);
    setStepCount(0);
  };

  const handleRunSimulation = async (mode) => {
    if (!selectedFile) {
      alert("Please upload a .bin file first.");
      return;
    }

    const formData = new FormData();
    formData.append('binfile', selectedFile);
    formData.append('mode', mode);

    setLoading(true);
    setSimOutput('');
    setGraphicsStatus(null);
    setHasSimulationEnded(false);
    setStepCount(0);

    try {
      const response = await fetch('http://localhost:5001/simulate', {
        method: 'POST',
        body: formData,
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || `Server error: ${response.statusText}`);
      }

      if (mode === 'full') {
        const result = await response.text();
        setSimOutput(result);
        setGraphicsStatus("✅ Full simulation completed");
        setHasSimulationEnded(true);
      } else if (mode === 'step') {
        const result = await response.json();
        if (result.error) {
          throw new Error(result.error);
        }
        setProcessId(result.process_id);
        setIsStepping(true);
        setSimOutput(`🚶 Step-by-step simulation started (Process ID: ${result.process_id})\n\n${result.initial_output}`);
        setGraphicsStatus("🎯 Ready for step-by-step execution");
      }

    } catch (error) {
      setSimOutput(`❌ Error: ${error.message}`);
      setProcessId(null);
      setIsStepping(false);
      setHasSimulationEnded(true);
      setGraphicsStatus("❌ Simulation failed");
    } finally {
      setLoading(false);
    }
  };

  const handleNextStep = async () => {
    if (!processId) return;

    setLoading(true);
    try {
      const response = await fetch('http://localhost:5001/step_simulation', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          process_id: processId,
          command: '\n' // Send newline to continue
        }),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || `Server error: ${response.statusText}`);
      }

      const result = await response.json();

      // Append new output to existing output
      setSimOutput(prevOutput =>
          prevOutput + `\n--- Step ${result.step_count} ---\n${result.output}`
      );

      setStepCount(result.step_count);

      if (result.terminated) {
        setSimOutput(prevOutput =>
            prevOutput + `\n\n🏁 Simulation completed after ${result.step_count} steps.`
        );
        setProcessId(null);
        setIsStepping(false);
        setHasSimulationEnded(true);
        setGraphicsStatus(`✅ Simulation completed in ${result.step_count} steps`);
      } else {
        setGraphicsStatus(`🎯 Step ${result.step_count} completed - Ready for next step`);
      }

    } catch (error) {
      setSimOutput(prevOutput =>
          prevOutput + `\n❌ Error during step execution: ${error.message}`
      );
      setProcessId(null);
      setIsStepping(false);
      setHasSimulationEnded(true);
      setGraphicsStatus("❌ Step execution failed");
    } finally {
      setLoading(false);
    }
  };

  const handleStopSimulation = async () => {
    if (!processId) return;

    setLoading(true);
    try {
      const response = await fetch('http://localhost:5001/end_simulation', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ process_id: processId }),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || `Server error: ${response.statusText}`);
      }

      const result = await response.json();
      setSimOutput(prevOutput =>
          prevOutput + `\n\n⏹️ ${result.status || "Simulation stopped by user"}`
      );
      setProcessId(null);
      setIsStepping(false);
      setHasSimulationEnded(true);
      setGraphicsStatus(`⏹️ Simulation stopped after ${stepCount} steps`);

    } catch (error) {
      setSimOutput(prevOutput =>
          prevOutput + `\n❌ Error stopping simulation: ${error.message}`
      );
      setGraphicsStatus("❌ Error stopping simulation");
    } finally {
      setLoading(false);
    }
  };

  const handleClear = async () => {
    // If there's an active simulation, stop it first
    if (isStepping && processId) {
      await handleStopSimulation();
    }

    setSimOutput('');
    setSelectedFile(null);
    setFileName('');
    setGraphicsStatus(null);
    setProcessId(null);
    setIsStepping(false);
    setHasSimulationEnded(false);
    setStepCount(0);
  };

  const handleGetStartedClick = () => {
    setClicked(true);
    setTimeout(() => {
      // Consider removing this if you want to stay in the same React app
      window.location.href = 'simulate.html';
    }, 150);
  };

  return (
      <div className="disassembler-container">
        <h2>⚙️ ZX16 Simulator Interface</h2>

        <div className="file-upload-section">
          <input type="file" accept=".bin" onChange={handleFileChange} />
          {fileName && <p className="file-info">📄 Selected: {fileName}</p>}
        </div>

        <div className="button-group" style={{ marginBottom: 10 }}>
          {/* Show simulation start buttons when not stepping */}
          {!isStepping && (
              <>
                <button
                    onClick={() => handleRunSimulation('full')}
                    disabled={loading || !selectedFile || hasSimulationEnded}
                    className="btn btn-primary"
                >
                  ▶️ {loading ? 'Running Full...' : 'Run Full Simulation'}
                </button>
                <button
                    onClick={() => handleRunSimulation('step')}
                    disabled={loading || !selectedFile || hasSimulationEnded}
                    className="btn btn-secondary"
                >
                  🚶 {loading ? 'Starting Step...' : 'Run Step-by-Step'}
                </button>
              </>
          )}

          {/* Show step control buttons when stepping */}
          {isStepping && !hasSimulationEnded && (
              <>
                <button
                    onClick={handleNextStep}
                    disabled={loading}
                    className="btn btn-success"
                >
                  ➡️ {loading ? 'Stepping...' : `Next Step (${stepCount + 1})`}
                </button>
                <button
                    onClick={handleStopSimulation}
                    disabled={loading}
                    className="btn btn-danger"
                >
                  ⏹️ Stop Simulation
                </button>
              </>
          )}

          <button
              onClick={handleClear}
              disabled={loading}
              className="btn btn-secondary"
          >
            🧹 Clear
          </button>
        </div>

        {/* Status Display */}
        {graphicsStatus && (
            <div className="status-display" style={{
              marginBottom: 10,
              padding: '8px 12px',
              backgroundColor: '#f0f8ff',
              border: '1px solid #ccc',
              borderRadius: '4px',
              fontWeight: 'bold'
            }}>
              {graphicsStatus}
            </div>
        )}

        {/* Output Display */}
        {simOutput && (
            <div className="output-container">
              <h3>📋 Simulation Output:</h3>
              <pre
                  style={{
                    whiteSpace: 'pre-wrap',
                    maxHeight: '500px',
                    overflowY: 'auto',
                    border: '1px solid #ccc',
                    padding: '15px',
                    backgroundColor: '#f9f9f9',
                    fontSize: '14px',
                    fontFamily: 'monospace',
                    borderRadius: '4px'
                  }}
              >
            {simOutput}
          </pre>
            </div>
        )}

        {/* Get Started Button */}
        <button
            className={`btn btn-primary ${clicked ? 'clicked' : ''}`}
            onClick={handleGetStartedClick}
            style={{ marginTop: '2rem' }}
        >
          🚀 Get Started
        </button>
      </div>
  );
}

export default App;
